await bash("cd /workspace && /opt/venv/bin/python - <<'EOF'
import time
from collections import deque
from lz import _make_log_corpus, MIN_MATCH, MAX_MATCH, WINDOW, MAX_CHAIN

data = _make_log_corpus()
n=len(data)
table={}
i=0
stats={'m':0,'d<=256':0,'d<=512':0,'l<=66':0,'d256_l66':0}
tot=0
while i<n:
    best=0;bd=0
    if i+3<=n:
        key=data[i:i+3]
        b=table.get(key)
        if b:
            lim=i-WINDOW
            while b and b[0]<=lim: b.popleft()
            c=0
            for pos in reversed(b):
                d=i-pos
                if d==0 or d>WINDOW: break
                l=3;s=pos+3;t=i+3
                ml=min(MAX_MATCH,n-i)
                while l<ml and data[s]==data[t]: s+=1;t+=1;l+=1
                if l>best: best=l;bd=d
                c+=1
                if c>=MAX_CHAIN: break
    if best>=3:
        stats['m']+=1; tot+=best
        if bd<=256: stats['d<=256']+=1
        if bd<=512: stats['d<=512']+=1
        if best<=66: stats['l<=66']+=1
        if bd<=256 and best<=66: stats['d256_l66']+=1
        e=i+best
        while i<e:
            p=i
            if p+3<=n:
                k=data[p:p+3]
                q=table.get(k)
                if q is None: table[k]=deque((p,))
                else:
                    q.append(p)
                    while q[0]<=p-WINDOW: q.popleft()
            i+=1
    else:
        p=i
        if p+3<=n:
            k=data[p:p+3]
            q=table.get(k)
            if q is None: table[k]=deque((p,))
            else:
                q.append(p)
                while q[0]<=p-WINDOW: q.popleft()
        i+=1
print(stats, 'avg len', tot/stats['m'])
EOF")
